                          });
                          const sortedRooms = Object.values(roomStats).sort((a, b) => b.totalBookings - a.totalBookings);
                          filteredTopRoomType = sortedRooms[0];
                        }
                      }

                      return (
                        <>
                          {validRevenue.length > 0 && filteredTopHotel && (
