import React, { useState, useEffect } from 'react';
import { useSearchParams, useNavigate } from 'react-router-dom';
import { Eye, EyeOff, Home as HomeIcon, CheckCircle2, AlertCircle, ArrowLeft } from 'lucide-react';
import axios from 'axios';
import { showAlert } from '../utils/alert';
import './Auth.css';

const Auth = () => {
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const [isLogin, setIsLogin] = useState(searchParams.get('mode') !== 'register');
  const [isForgotMode, setIsForgotMode] = useState(false);
  const [isOtpStep, setIsOtpStep] = useState(false);
  const [otpToken, setOtpToken] = useState('');
  const [otp, setOtp] = useState('');

  // Form State
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [phone, setPhone] = useState('');
  const [rememberMe, setRememberMe] = useState(false);
  const [termsAccepted, setTermsAccepted] = useState(false);

  // UI State
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [toast, setToast] = useState({ visible: false, message: '', type: 'success' });
  const [emailError, setEmailError] = useState('');

  const showToastMessage = (message, type = 'success') => {
    setToast({ visible: true, message, type });
    setTimeout(() => {
      setToast({ visible: false, message: '', type: 'success' });
    }, 3000);
  };

  useEffect(() => {
    if (searchParams.get('expired') === 'true') {
      showToastMessage('Phiên đăng nhập hết hạn, vui lòng đăng nhập lại.', 'error');
    }
  }, [searchParams]);

  const evaluatePassword = (pwd) => {
    if (!pwd) return { score: 0, text: '', color: 'bg-gray-200' };

    let score = 0;
    const hasLettersAndNumbers = /[a-zA-Z]/.test(pwd) && /[0-9]/.test(pwd);
    const hasSpecial = /[^A-Za-z0-9]/.test(pwd);
    const hasUpperAndLower = /[a-z]/.test(pwd) && /[A-Z]/.test(pwd);

    if (pwd.length >= 6) {
      if (pwd.length >= 8 && hasLettersAndNumbers && hasUpperAndLower && hasSpecial) {
        score = 3; // Mạnh
      } else if (hasLettersAndNumbers || pwd.length >= 8) {
        score = 2; // Tạm ổn
      } else {
        score = 1; // Yếu
      }
    } else {
      score = 1; // Yếu (Dưới 6 ký tự)
    }

    if (score === 1) return { score, text: 'Mật khẩu quá yếu', color: 'bg-danger' };
    if (score === 2) return { score, text: 'Mật khẩu tạm ổn', color: 'bg-warning' };
    if (score === 3) return { score, text: 'Mật khẩu rất mạnh', color: 'bg-success' };
  };

  const pwdStrength = evaluatePassword(password);
  const isPasswordsMatch = password && confirmPassword && password === confirmPassword;

  const handlePhoneChange = (e) => {
    const value = e.target.value;
    if (value === '' || /^[0-9\b]+$/.test(value)) {
      setPhone(value);
    }
  };

  const handleLoginSubmit = async (e) => {
    e.preventDefault();
    try {
      const res = await axios.post('http://localhost:5000/api/auth/login', {
        email: email.trim(),
        password: password.trim()
      });
      if (res.data.success) {
        sessionStorage.setItem('token', res.data.token);
        sessionStorage.setItem('isLoggedIn', 'true');
        sessionStorage.setItem('user', JSON.stringify(res.data.user));
        showToastMessage('Đăng nhập thành công!', 'success');

        // Nếu là Admin (roleId = 1) hoặc Owner (roleId = 2) hoặc Staff (roleId = 4) thì chuyển hướng thẳng vào trang quản trị
        setTimeout(() => {
          if ([1, 2, 4].includes(parseInt(res.data.user.roleId))) {
            navigate('/admin');
          } else {
            navigate('/');
          }
        }, 1500);
      }
    } catch (err) {
      console.error("Lỗi đăng nhập:", err);
      const errorMsg = err.response?.data?.error || 'Sai email hoặc mật khẩu!';
      showAlert('Lỗi Đăng Nhập', errorMsg, 'error');
    }
  };

  const handleRegisterSubmit = async (e) => {
    e.preventDefault();
    try {
      setEmailError('');
      const res = await axios.post('http://localhost:5000/api/auth/register', { email, password, phone });
      if (res.data.success) {
        sessionStorage.setItem('token', res.data.token);
        sessionStorage.setItem('isLoggedIn', 'true');
        sessionStorage.setItem('user', JSON.stringify(res.data.user));
        showToastMessage('Tạo tài khoản thành công! Đang chuyển hướng...', 'success');
        setTimeout(() => navigate('/'), 1500);
      }
    } catch (err) {
      console.error("Lỗi đăng ký:", err);
      const errorMsg = err.response?.data?.error || 'Đăng ký thất bại!';
      showAlert('Lỗi Đăng Ký', errorMsg, 'error');
      if (errorMsg.includes('Email')) {
        setEmailError(errorMsg);
      }
    }
  };

  const handleForgotPasswordSubmit = async (e) => {
    e.preventDefault();
    if (!email) {
      showToastMessage('Vui lòng nhập email của bạn.', 'error');
      return;
    }

    try {
      showToastMessage('Đang xử lý...', 'success');
      const res = await axios.post('http://localhost:5000/api/auth/forgot-password', { email: email.trim() });
      if (res.data.success) {
        showToastMessage(res.data.message, 'success');
        if (res.data.otpToken) {
          setOtpToken(res.data.otpToken);
          setIsOtpStep(true);
        } else {
          setTimeout(() => { setIsForgotMode(false); }, 3000);
        }
      }
    } catch (err) {
      console.error("Lỗi quên mật khẩu:", err);
      const errorMsg = err.response?.data?.error || 'Có lỗi xảy ra, vui lòng thử lại!';
      showToastMessage(errorMsg, 'error');
    }
  };

  const handleResetPasswordSubmit = async (e) => {
    e.preventDefault();
    if (!isPasswordsMatch) {
      showToastMessage('Mật khẩu không khớp!', 'error');
      return;
    }
    if (pwdStrength.score < 2) {
      showToastMessage('Mật khẩu quá yếu!', 'error');
      return;
    }

    try {
      showToastMessage('Đang xử lý...', 'success');
      const res = await axios.post('http://localhost:5000/api/auth/reset-password', {
        otpToken,
        otp,
        newPassword: password
      });

      if (res.data.success) {
        showToastMessage(res.data.message, 'success');
        setTimeout(() => {
          setIsForgotMode(false);
          setIsOtpStep(false);
          setOtpToken('');
          setOtp('');
          setPassword('');
          setConfirmPassword('');
        }, 2000);
      }
    } catch (err) {
      console.error("Lỗi đặt lại mật khẩu:", err);
      const errorMsg = err.response?.data?.error || 'Có lỗi xảy ra, vui lòng thử lại!';
      showToastMessage(errorMsg, 'error');
    }
  };

  const isRegisterValid = email && phone && pwdStrength.score >= 2 && isPasswordsMatch && termsAccepted;

  return (
    <div className="auth-container">
      {/* Toast Notification */}
      <div className={`toast-notification ${toast.visible ? 'show' : ''} ${toast.type}`}>
        {toast.type === 'success' ? <CheckCircle2 size={20} /> : <AlertCircle size={20} />}
        <span>{toast.message}</span>
      </div>

      <div className="auth-split">
        {/* Left Side: Visual */}
        <div className="auth-visual">
          <div className="visual-overlay"></div>
          <img src="/images/login-bg.jpg" alt="Bảo Lộc Landscape" />
          <div className="visual-content">
            <div className="brand" onClick={() => navigate('/')} title="Quay lại Trang chủ">
              <ArrowLeft size={28} style={{ marginRight: '4px', opacity: 0.9 }} />
              <HomeIcon size={28} />
              <span>BaoLoc Stay</span>
            </div>
            <div className="slogan">
              <h2>Trải nghiệm sự bình yên</h2>
              <p>Khám phá không gian nghỉ dưỡng tuyệt vời nhất tại Bảo Lộc cùng hàng ngàn tiện ích đẳng cấp.</p>
            </div>
          </div>
        </div>

        {/* Right Side: Form */}
        <div className="auth-form-wrapper">
          <div className="auth-form-container">
            {isForgotMode ? (
              // ================= FORGOT PASSWORD FORM =================
              <div className="auth-form-block animate-fade-in">
                {isOtpStep ? (
                  // BƯỚC 2: NHẬP OTP VÀ MẬT KHẨU MỚI
                  <>
                    <div className="form-header">
                      <h2>Nhập mã OTP</h2>
                      <p>Mã OTP đã được gửi đến <strong>{email}</strong>.</p>
                    </div>
                    <form onSubmit={handleResetPasswordSubmit} className="auth-form">
                      <div className="input-group">
                        <label>Mã OTP (6 chữ số)</label>
                        <input
                          type="text"
                          placeholder="Nhập mã OTP"
                          value={otp}
                          onChange={(e) => setOtp(e.target.value)}
                          maxLength={6}
                          required
                          style={{ fontSize: '20px', letterSpacing: '2px', textAlign: 'center' }}
                        />
                      </div>
                      <div className="input-group">
                        <label>Mật khẩu mới</label>
                        <div className="password-input">
                          <input
                            type={showPassword ? "text" : "password"}
                            placeholder="Tạo mật khẩu mới"
                            value={password}
                            onChange={(e) => setPassword(e.target.value)}
                            required
                          />
                          <button type="button" className="eye-btn" onClick={() => setShowPassword(!showPassword)}>
                            {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                          </button>
                        </div>
                        {password && (
                          <div className="pwd-strength-meter">
                            <div className="pwd-progress-bar">
                              <div className={`pwd-progress ${pwdStrength.color}`} style={{ width: `${(pwdStrength.score / 3) * 100}%` }}></div>
                            </div>
                            <span className={`pwd-text text-${pwdStrength.color.replace('bg-', '')}`}>{pwdStrength.text}</span>
                          </div>
                        )}
                      </div>
                      <div className="input-group">
                        <label>Xác nhận mật khẩu mới</label>
                        <div className="password-input">
                          <input
                            type={showConfirmPassword ? "text" : "password"}
                            placeholder="Xác nhận mật khẩu mới"
                            value={confirmPassword}
                            onChange={(e) => setConfirmPassword(e.target.value)}
                            required
                          />
                          <button type="button" className="eye-btn" onClick={() => setShowConfirmPassword(!showConfirmPassword)}>
                            {showConfirmPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                          </button>
                        </div>
                        {confirmPassword && (
                          <span className={`confirm-text ${isPasswordsMatch ? 'text-success' : 'text-danger'}`}>
                            {isPasswordsMatch ? 'Mật khẩu khớp' : 'Mật khẩu không khớp'}
                          </span>
                        )}
                      </div>
                      <button type="submit" className="btn-submit" disabled={!otp || otp.length < 6 || !isPasswordsMatch || pwdStrength.score < 2}>
                        Xác nhận & Đổi mật khẩu
                      </button>
                    </form>
                  </>
                ) : (
                  // BƯỚC 1: NHẬP EMAIL
                  <>
                    <div className="form-header">
                      <h2>Quên mật khẩu</h2>
                      <p>Nhập email của bạn, chúng tôi sẽ gửi mã OTP khôi phục.</p>
                    </div>
                    <form onSubmit={handleForgotPasswordSubmit} className="auth-form">
                      <div className="input-group">
                        <label>Email</label>
                        <input
                          type="email"
                          placeholder="Nhập email của bạn"
                          value={email}
                          onChange={(e) => setEmail(e.target.value)}
                          required
                        />
                      </div>
                      <button type="submit" className="btn-submit" disabled={!email}>
                        Gửi mã OTP
                      </button>
                    </form>
                  </>
                )}

                <div className="auth-switch">
                  <span>Nhớ mật khẩu rồi? </span>
                  <button type="button" className="switch-btn" onClick={() => { setIsForgotMode(false); setIsOtpStep(false); }}>Quay lại đăng nhập</button>
                </div>
              </div>
            ) : isLogin ? (
              // ================= LOGIN FORM =================
              <div className="auth-form-block animate-fade-in">
                <div className="form-header">
                  <h2>Đăng nhập</h2>
                  <p>Vui lòng đăng nhập để tiếp tục</p>
                </div>

                <form onSubmit={handleLoginSubmit} className="auth-form">
                  <div className="input-group">
                    <label>Email</label>
                    <input
                      type="email"
                      placeholder="Nhập email của bạn"
                      value={email}
                      onChange={(e) => setEmail(e.target.value)}
                      required
                    />
                  </div>

                  <div className="input-group">
                    <label>Mật khẩu</label>
                    <div className="password-input">
                      <input
                        type={showPassword ? "text" : "password"}
                        placeholder="Nhập mật khẩu"
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                        required
                      />
                      <button type="button" className="eye-btn" onClick={() => setShowPassword(!showPassword)}>
                        {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                      </button>
                    </div>
                  </div>

                  <div className="form-actions">
                    <label className="checkbox-container">
                      <input
                        type="checkbox"
                        checked={rememberMe}
                        onChange={(e) => setRememberMe(e.target.checked)}
                      />
                      <span>Ghi nhớ đăng nhập</span>
                    </label>
                    <a href="#" className="forgot-link" onClick={(e) => { e.preventDefault(); setIsForgotMode(true); }}>Quên mật khẩu?</a>
                  </div>

                  <button type="submit" className="btn-submit" disabled={!email || !password}>
                    Đăng nhập
                  </button>
                </form>

                <div className="auth-switch">
                  <span>Bạn chưa có tài khoản? </span>
                  <button type="button" className="switch-btn" onClick={() => setIsLogin(false)}>Đăng ký ngay</button>
                </div>
              </div>
            ) : (
              // ================= REGISTER FORM =================
              <div className="auth-form-block animate-fade-in">
                <div className="form-header">
                  <h2>Tạo tài khoản mới</h2>
                  <p>Điền thông tin bên dưới để tham gia cùng chúng tôi</p>
                </div>

                <form onSubmit={handleRegisterSubmit} className="auth-form">
                  <div className="input-group">
                    <label>Email</label>
                    <input
                      type="email"
                      placeholder="Nhập email của bạn"
                      className={emailError ? 'input-error' : ''}
                      value={email}
                      onChange={(e) => {
                        setEmail(e.target.value);
                        if (emailError) setEmailError('');
                      }}
                      required
                    />
                    {emailError && <span className="error-text">{emailError}</span>}
                  </div>

                  <div className="input-group">
                    <label>Số điện thoại</label>
                    <input
                      type="text"
                      placeholder="Nhập số điện thoại"
                      value={phone}
                      onChange={handlePhoneChange}
                      required
                    />
                  </div>

                  <div className="input-group">
                    <label>Mật khẩu</label>
                    <div className="password-input">
                      <input
                        type={showPassword ? "text" : "password"}
                        placeholder="Tạo mật khẩu"
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                        required
                      />
                      <button type="button" className="eye-btn" onClick={() => setShowPassword(!showPassword)}>
                        {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                      </button>
                    </div>

                    {/* Password Strength Meter */}
                    {password && (
                      <div className="pwd-strength-meter">
                        <div className="pwd-progress-bar">
                          <div className={`pwd-progress ${pwdStrength.color}`} style={{ width: `${(pwdStrength.score / 3) * 100}%` }}></div>
                        </div>
                        <span className={`pwd-text text-${pwdStrength.color.replace('bg-', '')}`}>{pwdStrength.text}</span>
                      </div>
                    )}
                  </div>

                  <div className="input-group">
                    <label>Nhập lại mật khẩu</label>
                    <div className="password-input">
                      <input
                        type={showConfirmPassword ? "text" : "password"}
                        placeholder="Xác nhận mật khẩu"
                        value={confirmPassword}
                        onChange={(e) => setConfirmPassword(e.target.value)}
                        required
                      />
                      <button type="button" className="eye-btn" onClick={() => setShowConfirmPassword(!showConfirmPassword)}>
                        {showConfirmPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                      </button>
                    </div>
                    {confirmPassword && (
                      <span className={`confirm-text ${isPasswordsMatch ? 'text-success' : 'text-danger'}`}>
                        {isPasswordsMatch ? 'Mật khẩu khớp' : 'Mật khẩu không khớp'}
                      </span>
                    )}
                  </div>

                  <div className="form-actions register-actions">
                    <label className="checkbox-container">
                      <input
                        type="checkbox"
                        required
                        checked={termsAccepted}
                        onChange={(e) => setTermsAccepted(e.target.checked)}
                      />
                      <span>Tôi đồng ý với Điều khoản và Chính sách bảo mật</span>
                    </label>
                  </div>

                  <button type="submit" className="btn-submit" disabled={!isRegisterValid}>
                    Tạo tài khoản
                  </button>
                </form>

                <div className="auth-switch">
                  <span>Đã có tài khoản? </span>
                  <button type="button" className="switch-btn" onClick={() => setIsLogin(true)}>Đăng nhập</button>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Auth;

import { useState } from 'react';
import { useNavigate, useParams, useSearchParams } from 'react-router-dom';
import { Copy, CheckCircle } from 'lucide-react';
import axios from 'axios';
import { showAlert } from '../utils/alert';
import Header from '../components/Header';
import Footer from '../components/Footer';
import './Checkout.css';

const Checkout = () => {
  const navigate = useNavigate();
  const { id: bookingId } = useParams();
  const [searchParams] = useSearchParams();
  
  const initialAmount = parseInt(searchParams.get('amount')) || 0;
  const initialTotal = parseInt(searchParams.get('total')) || initialAmount;
  const hotelName = searchParams.get('hotel') || 'Homestay';
  const roomName = searchParams.get('room') || 'Phòng Tiêu Chuẩn';

  const [amount, setAmount] = useState(initialAmount);
  const [total, setTotal] = useState(initialTotal);
  const [copied, setCopied] = useState('');
  const [discount, setDiscount] = useState('');
  const [discountAmount, setDiscountAmount] = useState(0);
  const [discountPercent, setDiscountPercent] = useState(0);

  const [savedVouchers, setSavedVouchers] = useState([]);
  const [showVoucherList, setShowVoucherList] = useState(false);

  React.useEffect(() => {
    const fetchVouchers = async () => {
      try {
        const token = sessionStorage.getItem('token');
        if (!token) return;
        const res = await axios.get('http://localhost:5000/api/users/my-promotions', {
          headers: { Authorization: `Bearer ${token}` }
        });
        if (res.data.success) {
          setSavedVouchers(res.data.data.filter(v => !v.is_used && new Date(v.valid_until) >= new Date()));
        }
      } catch (e) {
        console.error(e);
      }
    };
    fetchVouchers();
  }, []);

  const handleCopy = (text, type) => {
    navigator.clipboard.writeText(text);
    setCopied(type);
    setTimeout(() => setCopied(''), 2000);
  };

  const handleApplyDiscount = async () => {
    if (!discount.trim()) return showAlert('Lỗi', 'Vui lòng nhập mã giảm giá', 'warning');
    try {
      const token = sessionStorage.getItem('token');
      const res = await axios.post(`http://localhost:5000/api/bookings/${bookingId}/apply-promotion`, 
        { discount_code: discount },
        { headers: { Authorization: `Bearer ${token}` } }
      );
      if (res.data.success) {
        setDiscountPercent(res.data.discount_percent);
        setDiscountAmount(res.data.discount_amount);
        setAmount(res.data.new_deposit);
        // Do API đang tính new_deposit là 30% của newTotal
        showAlert('Thành công', res.data.message, 'success');
      }
    } catch (err) {
      const msg = err.response?.data?.error || 'Mã giảm giá không hợp lệ';
      showAlert('Lỗi', msg, 'error');
    }
  };

  const transferMsg = `THANH TOAN DH ${bookingId}`;
  const qrUrl = `https://img.vietqr.io/image/vcb-10123456789-compact2.png?amount=${amount}&addInfo=${encodeURIComponent(transferMsg)}&accountName=CHU%20HOMESTAY%20BAO%20LOC%20STAY`;

  const handleFinish = async () => {
    try {
      const token = sessionStorage.getItem('token');
      if (!token) {
        await showAlert('Hết phiên đăng nhập', 'Phiên đăng nhập đã hết hạn, vui lòng đăng nhập lại!', 'warning');
        navigate('/auth');
        return;
      }
      
      // Gọi API báo đã thanh toán lên Backend
      const res = await axios.post(`http://localhost:5000/api/bookings/${bookingId}/notify-paid`, {}, {
        headers: { Authorization: `Bearer ${token}` }
      });
      
      if (res.data.success) {
        await showAlert('Thành công', 'Đã gửi yêu cầu xác nhận thanh toán. Đơn hàng sẽ được duyệt trong vòng 15 phút. Vui lòng xem hóa đơn biên nhận.', 'success');
        navigate(`/invoice/${bookingId}`);
      }
    } catch (err) {
      console.error(err);
      const backendError = err.response?.data?.message || err.response?.data?.error;
      await showAlert('Lỗi thanh toán', backendError ? `Lỗi: ${backendError}` : 'Có lỗi xảy ra khi xác nhận thanh toán, hệ thống sẽ ghi nhận sau.', 'error');
      navigate('/profile');
    }
  };

  return (
    <>
      <Header />
      <div className="checkout-page container">
      <div className="checkout-header">
        <h1>Thanh toán đặt phòng</h1>
        <p>Vui lòng hoàn tất thanh toán trong vòng 15 phút</p>
      </div>

      <div className="checkout-layout">
        <div className="checkout-summary">
          <div className="glass-panel summary-box">
            <h2>Tóm tắt đơn hàng</h2>
            
            <div className="summary-details">
              <div className="summary-item">
                <span className="label">Homestay:</span>
                <span className="value">{hotelName}</span>
              </div>
              <div className="summary-item">
                <span className="label">Phòng:</span>
                <span className="value">{roomName}</span>
              </div>
            </div>

            <div className="discount-section" style={{ display: 'flex', gap: '10px', alignItems: 'center' }}>
              <input 
                type="text" 
                placeholder="Nhập mã giảm giá..." 
                value={discount}
                onChange={(e) => setDiscount(e.target.value)}
                style={{ flex: 1 }}
              />
              <button className="btn btn-outline" style={{ padding: '0 15px' }} onClick={() => setShowVoucherList(!showVoucherList)}>Ví Voucher</button>
              <button className="btn btn-primary" onClick={handleApplyDiscount}>Áp dụng</button>
            </div>

            {showVoucherList && (
              <div className="voucher-dropdown" style={{ background: '#f8fafc', padding: '15px', borderRadius: '8px', marginTop: '10px', border: '1px solid #e2e8f0' }}>
                <h4 style={{ margin: '0 0 10px 0', fontSize: '14px', color: '#0f172a' }}>Voucher của bạn</h4>
                {savedVouchers.length === 0 ? (
                  <p style={{ fontSize: '13px', color: '#64748b', margin: 0 }}>Bạn chưa có voucher nào hoặc voucher đã hết hạn/đã sử dụng.</p>
                ) : (
                  <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
                    {savedVouchers.map(v => (
                      <div key={v.saved_id} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', background: '#fff', padding: '10px', borderRadius: '6px', border: '1px solid #cbd5e1' }}>
                        <div>
                          <strong style={{ color: '#0f172a', fontSize: '15px' }}>{v.discount_code}</strong> 
                          <span style={{ color: '#ef4444', fontWeight: '600', marginLeft: '5px' }}>- Giảm {v.discount_percent}%</span>
                          <div style={{ fontSize: '12px', color: '#64748b', marginTop: '4px' }}>
                            {v.hotel_id ? `Dành cho ${v.hotel_name}` : 'Áp dụng Toàn hệ thống'}
                          </div>
                        </div>
                        <button className="btn btn-outline" style={{ padding: '6px 12px', fontSize: '13px' }} onClick={() => {
                          setDiscount(v.discount_code);
                          setShowVoucherList(false);
                        }}>Chọn</button>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            )}

            <div className="total-section" style={{ marginTop: '20px' }}>
              <div className="summary-item">
                <span>Tổng tiền phòng</span>
                <span>{total.toLocaleString('vi-VN')} ₫</span>
              </div>
              <div className="summary-item" style={{ color: discountAmount > 0 ? '#16a34a' : 'inherit' }}>
                <span>Giảm giá {discountPercent > 0 ? `(${discountPercent}%)` : ''}</span>
                <span>{discountAmount > 0 ? '-' : ''}{discountAmount.toLocaleString('vi-VN')} ₫</span>
              </div>
              <div className="summary-item grand-total">
                <span>Số tiền cần cọc</span>
                <strong>{amount.toLocaleString('vi-VN')} ₫</strong>
              </div>
            </div>
          </div>
        </div>

        <div className="checkout-payment">
          <div className="qr-box glass-panel">
            <h2>Chuyển khoản VietQR</h2>
            <p className="qr-instruction">Vui lòng quét mã QR hoặc chuyển khoản theo thông tin bên dưới</p>
            
            <div className="qr-image-wrapper">
              <img src={qrUrl} alt="VietQR" style={{ maxWidth: '280px', margin: '0 auto', borderRadius: '12px' }} />
            </div>

            <div className="bank-info">
              <div className="info-row">
                <div className="info-text">
                  <span className="info-label">Ngân hàng</span>
                  <strong>Vietcombank</strong>
                </div>
              </div>
              
              <div className="info-row">
                <div className="info-text">
                  <span className="info-label">Số tài khoản</span>
                  <strong>10123456789</strong>
                </div>
                <button className="copy-btn" onClick={() => handleCopy('10123456789', 'stk')}>
                  {copied === 'stk' ? <CheckCircle size={18} color="var(--status-confirmed)"/> : <Copy size={18} />}
                </button>
              </div>

              <div className="info-row">
                <div className="info-text">
                  <span className="info-label">Số tiền</span>
                  <strong className="amount">{amount.toLocaleString('vi-VN')} ₫</strong>
                </div>
                <button className="copy-btn" onClick={() => handleCopy(amount.toString(), 'amount')}>
                  {copied === 'amount' ? <CheckCircle size={18} color="var(--status-confirmed)"/> : <Copy size={18} />}
                </button>
              </div>

              <div className="info-row">
                <div className="info-text">
                  <span className="info-label">Nội dung chuyển khoản</span>
                  <strong>{transferMsg}</strong>
                </div>
                <button className="copy-btn" onClick={() => handleCopy(transferMsg, 'msg')}>
                  {copied === 'msg' ? <CheckCircle size={18} color="var(--status-confirmed)"/> : <Copy size={18} />}
                </button>
              </div>
            </div>

            <button className="btn btn-primary w-full complete-btn" onClick={handleFinish}>
              Tôi đã chuyển khoản
            </button>
            <button className="btn btn-outline w-full" style={{ marginTop: '10px', fontWeight: 600, padding: '12px' }} onClick={() => navigate('/')}>
              Về trang chủ
            </button>
          </div>
        </div>
      </div>
    </div>
      <Footer />
    </>
  );
};

export default Checkout;

